    @Test
    fun featuresMatchReference() {
        val f = SleepStager.features(samples)
        val getters: Map<String, (SleepStager.Features) -> Double> = mapOf(
            "hrRel" to { it.hrRel }, "hrM5" to { it.hrM5 }, "hrM15" to { it.hrM15 }, "hrSd5" to { it.hrSd5 },
            "hrSd15" to { it.hrSd15 }, "hrDiff" to { it.hrDiff }, "in5" to { it.in5 }, "in15" to { it.in15 },
            "in31" to { it.in31 }, "still" to { it.still }, "frac" to { it.frac }, "minute" to { it.minute },
            "sleepkind" to { it.sleepkind }, "hrB60" to { it.hrB60 }, "toEnd" to { it.toEnd }, "in61" to { it.in61 },
        )
        for ((name, values) in expected) {
            for ((i, v) in values) {
                val actual = getters.getValue(name)(f[i])
                assertTrue(abs(actual - v) < 1e-4, "$name[$i]: expected $v, got $actual")
            }
        }
    }

    @Test
    fun stagesMatchReference() {
        val code = mapOf(SleepStage.LIGHT to 'L', SleepStage.DEEP to 'D', SleepStage.AWAKE to 'W', SleepStage.REM to 'R')
        val raw = SleepStager.features(samples).map { code.getValue(SleepStager.classify(it)) }.joinToString("")
        assertEquals("LLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLDDDLLLLLLLLLLLLRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRLLRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRLLRRRRRRRRRRRRRRRRRRRRRR", raw)
        val smooth = SleepStager.stages(samples).map { code.getValue(it) }.joinToString("")
        assertEquals("LLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRRR", smooth)
    }
}
